def retry(max_attempts=3, backoff_factor=1):
    """
    Decorator that retries a function with exponential backoff on specified exceptions.

    Args:
        max_attempts (int): The maximum number of attempts to make. Defaults to 3.
        backoff_factor (int): The factor by which to increase the delay between attempts. Defaults to 1.

    Returns:
        function: The decorated function
    """
    def decorator(func):
        import time
        def wrapper(*args, **kwargs):
            attempts = 0
            delay = 1
            while attempts < max_attempts:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempts < max_attempts - 1:
                        time.sleep(delay)
                        delay = min(delay * backoff_factor, 60)  # cap the delay at 1 minute
                    else:
                        raise
                attempts += 1
        return wrapper
    return decorator

def safe_read_file(path):
    """
    Reads a file and returns its contents, returning None instead of raising an exception on any I/O error.

    :param path: The path to the file to be read.
    :return: The content of the file, or None if an I/O error occurs.
    """
    @retry(max_attempts=3, backoff_factor=1)
    def inner():
        with open(path, 'r') as file:
            return file.read()
    return inner() or None

def safe_json_load(json_str_or_file):
    """
    Safely loads JSON from a string or file, returning None on parse errors instead of raising.
    """
    try:
        import json
        return json.loads(json_str_or_file) if isinstance(json_str_or_file, str) else json.load(json_str_or_file)
    except json.JSONDecodeError:
        return None

def flatten_dict(nested_dict, prefix=''):
    """Recursively flattens a nested dictionary into a single-level dict with dot-separated compound keys."""
    flattened_dict = {}
    for key, value in nested_dict.items():
        new_key = f"{prefix}{key}" if prefix else key
        if isinstance(value, dict):
            flattened_dict.update(flatten_dict(value, new_key + '.'))
        else:
            flattened_dict[new_key] = value
    return flattened_dict

def cached_property(max_attempts=3, backoff_factor=1):
    def decorator(func):
        cache = {}
        def wrapper(self):
            if id(self) not in cache:
                cache[id(self)] = func(self)
            return cache[id(self)]
        @retry(max_attempts, backoff_factor)
        def func_wrapper(self):
            return wrapper(self)
        return func_wrapper
    return decorator

def flatten_list(nested_iterable, prefix=''):
    for element in nested_iterable:
        if isinstance(element, (list, tuple)):
            yield from flatten_list(element, prefix + '.')
        elif isinstance(element, dict):
            for key, value in flatten_dict(element, prefix + '.').items():
                yield key, value
        else:
            yield prefix, element

def group_by(iterable, key):
    result = {}
    for element in iterable:
        k = key(element)
        if k not in result:
            result[k] = []
        result[k].append(element)
    return result

def is_iterable(obj):
    """
    Returns True if the object supports iteration (has __iter__ or implements the iterator protocol), otherwise False.
    """
    try:
        iter(obj)
        return True
    except TypeError:
        return False

def unique_everseen(iterable):
    """Returns items from an iterable preserving order while removing duplicates."""
    seen = set()
    return (x for x in iterable if not (x in seen or seen.add(x)))

def flatten_nested_iterable(nested_iterable):
    """
    Recursively flattens any nested iterable (excluding strings/bytes) into a flat list.
    """
    def is_iterable(obj):
        return hasattr(obj, '__iter__') and not isinstance(obj, (str, bytes))

    def recursive_flatten(nested_iterable, prefix=[]):
        result = []
        for item in nested_iterable:
            if is_iterable(item):
                result.extend(recursive_flatten(item, prefix + [item]))
            else:
                result.append(prefix + [item])
        return result

    return recursive_flatten(nested_iterable, [])

def is_finite_number(value):
    """
    Returns True if the input is an int or float that is neither NaN nor infinite, otherwise False.
    """
    return isinstance(value, (int, float)) and not value != value and not (value == float('inf') or value == float('-inf'))

def flatten_dict_keys(nested_dict):
    """
    Returns a flat dictionary with dot-separated keys for nested dictionaries.
    """
    def flatten_dict(nested_dict, prefix=''):
        result = {}
        for k, v in nested_dict.items():
            new_key = prefix + k if prefix else k
            if isinstance(v, dict):
                result.update(flatten_dict(v, prefix=new_key + '.'))
            else:
                result[new_key] = v
        return result
    return flatten_dict(nested_dict)

def chunks(iterable, chunk_size):
    it = iter(iterable)
    while True:
        chunk = tuple(is_iterable(it) and [next(it) for _ in range(chunk_size - 1)] or [next(it)])
        if not chunk:
            break
        yield chunk

def flatten_json(nested_dict):
    """
    Flatten a nested dictionary into a single-level dict with dot-separated compound keys.

    Args:
        nested_dict (dict): The dictionary to be flattened.

    Returns:
        dict: The flattened dictionary.
    """
    def flatten_dict(nested_dict, prefix=''):
        flattened = {}
        for key, value in nested_dict.items():
            new_key = prefix + key if prefix else key
            if isinstance(value, dict):
                flattened.update(flatten_dict(value, new_key + '.'))
            else:
                flattened[new_key] = value
        return flattened
    return flatten_dict(nested_dict)
